<?php declare(strict_types=1);namespace NpmGateway\Http\Controllers;use NpmGateway\Contracts\CorporateToolsProviderInterface;use NpmGateway\Exceptions\Domain\{InvalidRmAuditException,RmAuditStateConflictException};use NpmGateway\Http\{AuthenticatedRequestContext,Request,Response};use NpmGateway\Security\CsrfService;use NpmGateway\Services\{CorporateAccessService,RmAuditQueryService,RmAuditService};use NpmGateway\Support\FlashSession;
final class CorporateRmAuditController{public function __construct(private readonly CorporateAccessService$access,private readonly RmAuditQueryService$q,private readonly RmAuditService$s,private readonly CorporateToolsProviderInterface$tools,private readonly CsrfService$csrf,private readonly FlashSession$flash,private readonly string$views){}
 public function index(Request$r,AuthenticatedRequestContext$c):Response{if(!$this->ok($c))return$this->deny();$status=(string)($r->query['status']??'');$propertyPublicId=(string)($r->query['property']??'');$search=trim((string)($r->query['search']??''));$audits=$this->q->corporateList($status,$propertyPublicId,$search);$counts=$this->q->counts(null,$status,$propertyPublicId,$search);$properties=$this->q->properties();return$this->render('index',$c,compact('audits','counts','properties','status','propertyPublicId','search'));}
 public function create(AuthenticatedRequestContext$c):Response{if(!$this->ok($c))return$this->deny();$properties=$this->q->properties();$input=(array)$this->flash->pull('rma_input',[]);$errors=(array)$this->flash->pull('rma_errors',[]);return$this->render('create',$c,compact('properties','input','errors'));}
 public function store(Request$r,AuthenticatedRequestContext$c):Response{if(!$this->ok($c))return$this->deny();if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.');try{$x=$this->s->create($r->post,$c->user);$this->flash->put('rma_success','RM Audit created successfully.');if(!$x['email_sent'])$this->flash->put('rma_warning','The audit was saved, but the manager notification could not be delivered.');return Response::redirect('/corporate/rm-audits/'.$x['public_id']);}catch(InvalidRmAuditException$e){$this->flash->put('rma_input',$e->input);$this->flash->put('rma_errors',$e->errors);return Response::redirect('/corporate/rm-audits/create');}}
 public function show(string$p,AuthenticatedRequestContext$c):Response{if(!$this->ok($c))return$this->deny();$audit=$this->q->detail($p);if(!$audit)return new Response(404,'Not Found');$input=(array)$this->flash->pull('rma_return_input',[]);$errors=(array)$this->flash->pull('rma_return_errors',[]);$success=(string)$this->flash->pull('rma_success','');$warning=(string)$this->flash->pull('rma_warning','');$error=(string)$this->flash->pull('rma_error','');return$this->render('show',$c,compact('audit','input','errors','success','warning','error'));}
 public function returnAudit(Request$r,string$p,AuthenticatedRequestContext$c):Response{if(!$this->ok($c))return$this->deny();if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.');try{$sent=$this->s->returnAudit($p,$r->post,$c->user);$this->flash->put('rma_success','RM Audit returned successfully.');if(!$sent)$this->flash->put('rma_warning','The audit was returned, but the manager notification could not be delivered.');}catch(InvalidRmAuditException$e){$this->flash->put('rma_return_input',$e->input);$this->flash->put('rma_return_errors',$e->errors);}catch(RmAuditStateConflictException){$this->flash->put('rma_error','This audit is no longer eligible to be returned.');}catch(\OutOfBoundsException){return new Response(404,'Not Found');}return Response::redirect('/corporate/rm-audits/'.$p);}
 private function ok(AuthenticatedRequestContext$c):bool{return$this->access->canAccessCategory($c,'rm-audit');}private function deny():Response{return new Response(403,'Forbidden',['Cache-Control'=>'private, no-store']);}private function render(string$v,AuthenticatedRequestContext$c,array$x):Response{$user=$c->user;$csrfToken=$this->csrf->token();$logoutCsrfToken=$csrfToken;$navbarCorporateItems=$this->tools->tools($c);extract($x);ob_start();require$this->views.'/corporate/rm-audits/'.$v.'.php';return new Response(200,(string)ob_get_clean(),['Cache-Control'=>'private, no-store']);}}
